/**
 * @nodegx/core: the values the page reads and the effects that redraw it when they change.
 *
 * This is the source of the npm package `@nodegx/core`, its types taken out and its files joined into one, so the
 * app needs nothing installed. `value(x)` holds a value; `effect(fn)` runs `fn` now and again whenever a value it
 * read changes; `derived(fn)` is a value computed from others. The rest is the machinery they share.
 *
 * Generated by the export, the same in every app. Change it if you like: nothing reads it but your own files.
 */

// ---- internal.ts ----

/**
 * The reactive graph and the turn scheduler.
 *
 * Nothing in here is exported from the package. It is the mechanism the primitives share, and it
 * exists as one file because the invalidation pass and the scheduler have to agree about what a
 * "turn" is — see CONTRACT.md C5.
 */

// ---------------------------------------------------------------------------
// Dependency tracking
// ---------------------------------------------------------------------------

let currentComputation = null;

/**
 * Records that the computation currently running read `source`.
 *
 * Outside a computation this is a single null check, which is the common case: generated code
 * reads values from event handlers far more often than from inside a `derived`.
 */
function track(source) {
  const computation = currentComputation;
  if (computation === null) return;

  if (source.dependents === null) source.dependents = new Set();
  source.dependents.add(computation);
  computation.sources.add(source);
}

/** Runs `compute` with `node` as the tracking target, restoring the previous target afterwards. */
function withTracking(node, compute) {
  const previous = currentComputation;
  currentComputation = node;
  try {
    return compute();
  } finally {
    currentComputation = previous;
  }
}

/** Runs `fn` with tracking suspended, so reads inside it create no dependency edges. */
function untracked(fn) {
  const previous = currentComputation;
  currentComputation = null;
  try {
    return fn();
  } finally {
    currentComputation = previous;
  }
}

/** Drops every edge into `node`, so a recomputation can record a fresh set. */
function clearSources(node) {
  for (const source of node.sources) {
    source.dependents?.delete(node);
  }
  node.sources.clear();
}

// ---------------------------------------------------------------------------
// Propagation
// ---------------------------------------------------------------------------

/**
 * Two-phase propagation, which is what makes the graph glitch-free (CONTRACT.md C6).
 *
 * Phase one walks the whole dependent subtree and marks it stale. Phase two notifies — the source's
 * own subscribers first, then every derived that was staled. By the time any subscriber runs, every
 * value it could read is already known to be stale, so reading it recomputes from current inputs
 * rather than returning a half-updated cache.
 *
 * `seen` is per-pass and deliberately not the `stale` flag: a derived that is *already* stale from
 * an earlier write must still be collected and notified again, because CONTRACT.md C2 says every
 * write is delivered.
 */
function propagate(source, notifySource) {
  runInTurn(() => {
    const dependents = source.dependents;

    if (dependents === null || dependents.size === 0) {
      notifySource();
      return;
    }

    const staled = [];
    const seen = new Set();
    collectStale(source, staled, seen);

    notifySource();

    for (let i = 0; i < staled.length; i++) {
      staled[i].notifyStale();
    }
  });
}

function collectStale(node, out, seen) {
  const dependents = node.dependents;
  if (dependents === null) return;

  for (const dependent of dependents) {
    if (seen.has(dependent)) continue;
    seen.add(dependent);
    dependent.stale = true;
    out.push(dependent);
    collectStale(dependent, out, seen);
  }
}

// ---------------------------------------------------------------------------
// The turn
// ---------------------------------------------------------------------------

class CyclicUpdateError extends Error {
  constructor(depth) {
    super(
      `@nodegx/core: update depth of ${depth} exceeded — a subscriber is writing to something it ` +
        'depends on. The interpreted runtime breaks this cycle silently and continues on the next ' +
        'frame; exported code should not contain one. Raise the limit with ' +
        'configureRuntime({ maxTurnDepth }) if this is genuinely intended.'
    );
    this.name = 'CyclicUpdateError';
  }
}

const defaultSchedule =
  typeof queueMicrotask === 'function' ? queueMicrotask : (flush) => Promise.resolve().then(flush);

let schedule = defaultSchedule;
let maxTurnDepth = 100;

let turnDepth = 0;
let batchDepth = 0;
let flushScheduled = false;
const pendingEffects = new Set();

/**
 * Runs `fn` as one nesting level of the current turn, guarded against runaway recursion.
 *
 * The limit is checked *before* incrementing so that the throw leaves the counter balanced: every
 * frame already on the stack still runs its own `finally`, unwinding the depth back to zero. A
 * counter that drifted would make the next unrelated write throw, which is the confusing failure
 * this shape avoids.
 */
function runInTurn(fn) {
  if (turnDepth >= maxTurnDepth) throw new CyclicUpdateError(maxTurnDepth);
  turnDepth++;
  try {
    return fn();
  } finally {
    turnDepth--;
    if (turnDepth === 0 && batchDepth === 0) scheduleFlush();
  }
}

/** Queues an effect to run when the turn settles. Re-queueing before the flush coalesces. */
function queueEffect(run) {
  pendingEffects.add(run);
  if (turnDepth === 0 && batchDepth === 0) scheduleFlush();
}

function cancelEffect(run) {
  pendingEffects.delete(run);
}

function scheduleFlush() {
  if (flushScheduled || pendingEffects.size === 0) return;
  flushScheduled = true;
  schedule(flushEffects);
}

function flushEffects() {
  flushScheduled = false;
  if (pendingEffects.size === 0) return;

  // Snapshot before running: an effect that writes may queue further effects, and those belong to
  // the next drain rather than to this one. This is the runtime's `callbacksAfterUpdate` swap
  // (nodecontext.ts:380-388).
  const running = Array.from(pendingEffects);
  pendingEffects.clear();

  for (let i = 0; i < running.length; i++) {
    running[i]();
  }

  if (pendingEffects.size > 0) scheduleFlush();
}

/**
 * Coalesces the end-of-turn effect flush across `fn`.
 *
 * It does **not** defer subscriber notification: CONTRACT.md C2 says every write is delivered, and
 * the ordering in EXP-001-TARGET-OUTPUT.md §4 depends on `set` having notified before the next
 * statement runs.
 */
function batch(fn) {
  batchDepth++;
  try {
    return fn();
  } finally {
    batchDepth--;
    if (batchDepth === 0 && turnDepth === 0) scheduleFlush();
  }
}

/** Runs every queued effect immediately. Exported for tests and for the EXP-003 trace harness. */
function flushSync() {
  flushEffects();
}

function configureRuntime(options) {
  if (options.schedule !== undefined) schedule = options.schedule;
  if (options.maxTurnDepth !== undefined) maxTurnDepth = options.maxTurnDepth;
}

/** Restores the shipped defaults. Used by tests; harmless in an app. */
function resetRuntime() {
  schedule = defaultSchedule;
  maxTurnDepth = 100;
  turnDepth = 0;
  batchDepth = 0;
  flushScheduled = false;
  pendingEffects.clear();
}

// ---- value.ts ----

/**
 * A piece of reactive state.
 *
 * The exported equivalent of a Variable node, and the building block the stores are made of.
 *
 * ```ts
 * const count = value(0);
 * count.subscribe((n) => console.log(n));
 * count.set(1); // logs 1
 * ```
 */
class Value {
  /** @internal */
  dependents = null;

  current;
  listeners = null;

  constructor(initial) {
    this.current = initial;
  }

  get() {
    track(this);
    return this.current;
  }

  /**
   * Writes a new value and notifies synchronously.
   *
   * There is deliberately **no equality check**: the interpreted runtime re-runs a port's setter
   * even when the value is unchanged (CONTRACT.md C2), and generated code can depend on that.
   * React absorbs the redundant work through its own `Object.is` bail-out in
   * `useSyncExternalStore`, so faithfulness costs nothing where it would have shown.
   */
  set(next) {
    this.current = next;
    propagate(this, () => this.emitToListeners(next));
  }

  /** `set` in terms of the previous value. Reads without creating a dependency edge. */
  update(fn) {
    this.set(fn(this.current));
  }

  subscribe(listener) {
    if (this.listeners === null) this.listeners = new Set();
    this.listeners.add(listener);
    return () => {
      this.listeners?.delete(listener);
    };
  }

  /** Reads without subscribing and without creating a dependency edge. */
  peek() {
    return this.current;
  }

  emitToListeners(next) {
    const listeners = this.listeners;
    if (listeners === null || listeners.size === 0) return;

    // Copied before iterating: a listener that unsubscribes another listener would otherwise
    // mutate the set mid-iteration, and the runtime's fan-out loop (outputproperty.ts:151) is a
    // fixed-length walk for the same reason.
    for (const listener of Array.from(listeners)) {
      listener(next);
    }
  }
}

/** Creates a {@link Value}. The exported equivalent of a Variable node. */
function value(initial) {
  return new Value(initial);
}

// ---- derived.ts ----

/**
 * A value computed from other values, recomputed on read when one of them has changed.
 *
 * This is the exported equivalent of an Expression node or a computed output port, and it is
 * modelled directly on how the interpreted runtime's output ports work: a port stores nothing and
 * calls its owner's getter on every read (CONTRACT.md C1). The only addition here is memoisation,
 * so reading a derived value ten times in one render computes it once.
 *
 * Dependencies are discovered automatically — whatever the compute function reads, it depends on.
 *
 * ```ts
 * const first = value('Ada');
 * const last = value('Lovelace');
 * const full = derived(() => `${first.get()} ${last.get()}`);
 * full.get(); // 'Ada Lovelace'
 * ```
 */
class Derived {
  /** @internal */
  dependents = null;
  /** @internal */
  stale = true;
  /** @internal */
  sources = new Set();

  compute;
  current;
  computed = false;
  listeners = null;

  constructor(compute) {
    this.compute = compute;
  }

  get() {
    track(this);
    if (this.stale || !this.computed) this.recompute();
    return this.current;
  }

  subscribe(listener) {
    if (this.listeners === null) this.listeners = new Set();
    this.listeners.add(listener);
    return () => {
      this.listeners?.delete(listener);
    };
  }

  /** Reads without subscribing and without creating a dependency edge in an enclosing computation. */
  peek() {
    if (this.stale || !this.computed) this.recompute();
    return this.current;
  }

  /**
   * Drops this value's dependency edges.
   *
   * Sources hold references to the derived values that read them, so a long-lived store keeps a
   * short-lived derived alive until this is called. Components created by the generator dispose in
   * their cleanup; the React hooks do it for you.
   */
  dispose() {
    clearSources(this);
    this.listeners = null;
    this.dependents = null;
  }

  /** @internal — called during propagation's notify phase, after every stale mark is set. */
  notifyStale() {
    const listeners = this.listeners;
    if (listeners === null || listeners.size === 0) return;

    // The value is read here rather than passed in, which is the whole point of the two-phase
    // pass: by now everything downstream of the write is marked stale, so this recomputation sees
    // a consistent graph rather than a mixture of fresh and cached inputs (CONTRACT.md C6).
    const next = this.get();
    for (const listener of Array.from(listeners)) {
      listener(next);
    }
  }

  recompute() {
    clearSources(this);
    this.current = withTracking(this, this.compute);
    this.stale = false;
    this.computed = true;
  }
}

/** Creates a {@link Derived}. The exported equivalent of an Expression node. */
function derived(compute) {
  return new Derived(compute);
}

/** Re-exported so a `derived` can read something without depending on it. */

// ---- signal.ts ----

/**
 * A discrete event, as distinct from a value.
 *
 * The exported equivalent of a Noodl signal port — a button's `onClick`, a Function node's
 * `Outputs.Done()`. Most signals never become one of these: when a signal's entire downstream is a
 * side effect inside the same component, the generator emits an ordinary handler, which is why
 * `/Nav` in EXP-001-TARGET-OUTPUT.md contains no library call at all. A `Signal` is generated when
 * the event has to cross a boundary the call graph cannot.
 *
 * ```ts
 * const promptSent = signal<string>();
 * promptSent.subscribe((text) => console.log(text));
 * promptSent.emit('hello');
 * ```
 *
 * **Every emit fires.** The interpreted runtime does not merge two pulses that happen in the same
 * frame — a signal port is edge-triggered and each pulse carries its own reset, so the handler runs
 * once per pulse (CONTRACT.md C4). Subscribers run synchronously and in subscription order, which
 * is what preserves the value-then-signal ordering generated code relies on
 * (EXP-001-TARGET-OUTPUT.md §4).
 */
class Signal {
  listeners = null;

  emit(payload) {
    const listeners = this.listeners;
    if (listeners === null || listeners.size === 0) return;

    runInTurn(() => {
      for (const listener of Array.from(listeners)) {
        listener(payload);
      }
    });
  }

  subscribe(listener) {
    if (this.listeners === null) this.listeners = new Set();
    this.listeners.add(listener);
    return () => {
      this.listeners?.delete(listener);
    };
  }

  /** Whether anything is listening. Mirrors the runtime's `hasConnections`. */
  get hasListeners() {
    return this.listeners !== null && this.listeners.size > 0;
  }
}

/** Creates a {@link Signal}. The exported equivalent of a signal output port. */
function signal() {
  return new Signal();
}

// ---- store.ts ----

/**
 * A named object of reactive state.
 *
 * The exported equivalent of a Global Store or an Object node. Reads go through a selector, which
 * is the shape a React developer already knows, and writes are a patch:
 *
 * ```ts
 * export const chat = store('chat', { title: 'Untitled conversation', messages: [] });
 *
 * // in a component
 * const title = useStore(chat, (s) => s.title);
 * // in a handler
 * chat.set({ title: draft });
 * ```
 *
 * Stores are registered by name, so calling `store('chat', …)` twice returns the same instance.
 * That is what "global" meant in the graph, and it also survives a hot reload — the second call
 * keeps the state the first one accumulated rather than resetting the app.
 */
class Store {
  /** @internal */
  dependents = null;

  name;

  /**
   * Increments on every write. The React binding uses it to cache a selector's result, so an
   * inline `(s) => s.title` does not have to be referentially stable to be cheap.
   */
  version = 0;

  state;
  initial;
  listeners = null;

  constructor(name, initial) {
    this.name = name;
    this.initial = { ...initial };
    this.state = { ...initial };
  }

  get() {
    track(this);
    return this.state;
  }

  /**
   * Merges a patch into the state and notifies synchronously.
   *
   * As with {@link Value.set}, there is no equality check — see CONTRACT.md C2. A function patch
   * receives the current state and returns the fields to change.
   */
  set(patch) {
    const fields = typeof patch === 'function' ? patch(this.state) : patch;
    this.state = { ...this.state, ...fields };
    this.version++;
    propagate(this, () => this.emitToListeners());
  }

  /** Reads one field. Equivalent to a Global Store Subscribe node with a single key. */
  select(key) {
    return this.get()[key];
  }

  subscribe(listener) {
    if (this.listeners === null) this.listeners = new Set();
    this.listeners.add(listener);
    return () => {
      this.listeners?.delete(listener);
    };
  }

  /** Reads without subscribing and without creating a dependency edge. */
  peek() {
    return this.state;
  }

  /** Restores the state the store was created with. */
  reset() {
    this.state = { ...this.initial };
    this.version++;
    propagate(this, () => this.emitToListeners());
  }

  emitToListeners() {
    const listeners = this.listeners;
    if (listeners === null || listeners.size === 0) return;

    for (const listener of Array.from(listeners)) {
      listener(this.state);
    }
  }
}

const registry = new Map();

/**
 * Creates or returns the named {@link Store}.
 *
 * @param name  the store's name, matching the `storeName` the graph used
 * @param initial  the state the store starts with, and what {@link Store.reset} restores
 */
function store(name, initial) {
  const existing = registry.get(name);
  if (existing !== undefined) return existing;

  const created = new Store(name, initial);
  registry.set(name, created);
  return created;
}

/** Forgets every registered store. Used by tests; an app has no reason to call it. */
function clearStores() {
  registry.clear();
}

// ---- collection.ts ----

/**
 * A reactive list.
 *
 * The exported equivalent of an Array / Collection node — the thing a `For Each` iterates.
 *
 * ```ts
 * const messages = collection<Message>([]);
 * messages.add({ id: '1', text: 'hello' });
 * ```
 *
 * **This is copy-on-write, and the interpreted runtime's Collection is not.** There, a Collection
 * is a Proxy over a real array whose mutating methods notify in place
 * (`packages/noodl-runtime/src/collection.ts`), so the array's identity never changes. Here, every
 * mutation produces a new array.
 *
 * The difference is deliberate and it is the one a React developer needs: `useMemo`, `React.memo`
 * and `useSyncExternalStore` all compare by identity, and a list that mutates in place is invisible
 * to every one of them. The cost is that code holding a reference to the previous array sees the
 * old contents — which is what a React developer expects, and what the graph's author could not
 * have relied on either way.
 */
class Collection {
  /** @internal */
  dependents = null;

  items;
  listeners = null;

  constructor(initial = []) {
    this.items = initial.slice();
  }

  get() {
    track(this);
    return this.items;
  }

  get size() {
    return this.get().length;
  }

  at(index) {
    return this.get()[index];
  }

  /** Replaces the whole list. */
  set(items) {
    this.items = items.slice();
    this.notify();
  }

  add(item) {
    this.set([...this.items, item]);
  }

  insert(index, item) {
    const next = this.items.slice();
    next.splice(index, 0, item);
    this.set(next);
  }

  /** Removes the first item strictly equal to `item`. Does nothing, and does not notify, if absent. */
  remove(item) {
    const index = this.items.indexOf(item);
    if (index === -1) return;
    this.removeAt(index);
  }

  removeAt(index) {
    if (index < 0 || index >= this.items.length) return;
    const next = this.items.slice();
    next.splice(index, 1);
    this.set(next);
  }

  clear() {
    if (this.items.length === 0) return;
    this.set([]);
  }

  /** Replaces every item for which `match` holds, using `update` to produce the replacement. */
  updateWhere(match, update) {
    let changed = false;
    const next = this.items.map((item) => {
      if (!match(item)) return item;
      changed = true;
      return update(item);
    });
    if (changed) this.set(next);
  }

  subscribe(listener) {
    if (this.listeners === null) this.listeners = new Set();
    this.listeners.add(listener);
    return () => {
      this.listeners?.delete(listener);
    };
  }

  /** Reads without subscribing and without creating a dependency edge. */
  peek() {
    return this.items;
  }

  notify() {
    propagate(this, () => {
      const listeners = this.listeners;
      if (listeners === null || listeners.size === 0) return;
      for (const listener of Array.from(listeners)) {
        listener(this.items);
      }
    });
  }
}

/** Creates a {@link Collection}. The exported equivalent of an Array / Collection node. */
function collection(initial = []) {
  return new Collection(initial);
}

// ---- events.ts ----

/**
 * The exported equivalent of Send Event and Receive Event nodes: a bus keyed by event name.
 *
 * Send and Receive nodes are matched by a string in the graph, not by a wire, so the exported form
 * has to be name-keyed too. Everything else about them is a {@link Signal}, which is what backs
 * each channel.
 *
 * Prefer {@link channel} in generated code — it gives the event a type and a module-level binding,
 * so a typo becomes a compile error rather than an event nobody receives:
 *
 * ```ts
 * export const conversationCleared = channel<void>('conversationCleared');
 * conversationCleared.emit();
 * ```
 */
const channels = new Map();

/** Creates or returns the named typed channel. */
function channel(name) {
  const existing = channels.get(name);
  if (existing !== undefined) return existing;

  const created = new Signal();
  channels.set(name, created);
  return created;
}

/** The untyped door onto the same channels, for dynamic event names. */
const events = {
  emit(name, payload) {
    channel(name).emit(payload);
  },
  on(name, listener) {
    return channel(name).subscribe(listener);
  }
};

/** Forgets every channel. Used by tests; an app has no reason to call it. */
function clearChannels() {
  channels.clear();
}

// ---- effect.ts ----

/**
 * Runs a function now, and again when anything it read has changed.
 *
 * This is the exported equivalent of a node that reacts rather than computes — writing to
 * `document.title`, persisting to local storage, opening a socket. Dependencies are discovered the
 * same way `derived` discovers them: whatever the function reads, it depends on.
 *
 * Re-runs are **deferred to the end of the turn and coalesced**, which is where the interpreted
 * runtime's frame drain lives (CONTRACT.md C5). Ten writes to the same value inside one handler
 * produce one re-run. The immediate first run is not deferred.
 *
 * Returning a function from the effect registers cleanup, run before each re-run and on dispose —
 * the same contract as React's `useEffect`, deliberately, because that is the one every reader
 * already knows.
 *
 * ```ts
 * const stop = effect(() => {
 *   document.title = chat.get().title;
 * });
 * ```
 *
 * @returns a function that stops the effect and runs its cleanup
 */
function effect(fn) {
  const node = new EffectNode(fn);
  node.execute();
  return () => node.dispose();
}

class EffectNode {
  dependents = null;
  stale = false;
  sources = new Set();

  fn;
  cleanup = undefined;
  disposed = false;

  /** Bound once so `queueEffect`'s Set can coalesce repeat schedules of the same effect. */
  run = () => {
    if (this.disposed) return;
    this.execute();
  };

  constructor(fn) {
    this.fn = fn;
  }

  execute() {
    if (this.cleanup !== undefined) {
      const cleanup = this.cleanup;
      this.cleanup = undefined;
      cleanup();
    }
    clearSources(this);
    this.stale = false;
    this.cleanup = withTracking(this, this.fn);
  }

  notifyStale() {
    if (this.disposed) return;
    queueEffect(this.run);
  }

  dispose() {
    if (this.disposed) return;
    this.disposed = true;
    cancelEffect(this.run);
    clearSources(this);
    if (this.cleanup !== undefined) {
      const cleanup = this.cleanup;
      this.cleanup = undefined;
      cleanup();
    }
  }
}

export {
  Value,
  value,
  Derived,
  derived,
  untracked,
  Signal,
  signal,
  Store,
  store,
  clearStores,
  Collection,
  collection,
  channel,
  events,
  clearChannels,
  effect,
  batch,
  flushSync,
  configureRuntime,
  resetRuntime,
  CyclicUpdateError
};
